<?php
declare(strict_types=1);
require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();
$students=$pdo->query("SELECT id,nama_lengkap,nis,kelas,level FROM students WHERE status='aktif' ORDER BY CAST(LEFT(kelas,1) AS UNSIGNED),kelas,nama_lengkap")->fetchAll();$studentId=(string)($_GET['student_id']??($students[0]['id']??''));$selected=null;foreach($students as $row)if($row['id']===$studentId){$selected=$row;break;}if(!$selected&&$students){$selected=$students[0];$studentId=$selected['id'];}
$existing=null;$payload=[];$period=format_month_year_id(date('Y-m-d'));if($selected){$stmt=$pdo->prepare('SELECT * FROM munaqosyah_exams WHERE student_id=? LIMIT 1');$stmt->execute([$studentId]);$existing=$stmt->fetch()?:null;if($existing)$payload=json_decode((string)$existing['hasil_ujian'],true)?:[];$stmt=$pdo->prepare("SELECT bulan_tahun FROM student_reports WHERE student_id=? AND jenis_rapor='munaqosyah' ORDER BY updated_at DESC LIMIT 1");$stmt->execute([$studentId]);$period=$stmt->fetchColumn()?:$period;}
$rows=$payload['rowsMunaqosyah']??[];$scoreValues=['kelancaran'=>80,'makhraj'=>80,'tajwid'=>80,'hafalan'=>80];foreach(array_values($rows) as $index=>$row){$key=array_keys($scoreValues)[$index]??null;if($key)$scoreValues[$key]=(float)($row['angka']??80);}$average=round(array_sum($scoreValues)/4,2);[$predicate]=predicate($average);$personal=$payload['kepribadianMunaqosyah']??[];
$pageTitle='Form Munaqosyah';require ROOT_PATH.'/includes/header.php';
?>
<div class="page-head"><div><h1 class="page-title">Form Munaqosyah</h1><p class="page-description">Input mengikuti komponen rekap Excel dan langsung memperbarui template rapor resmi sekolah.</p></div><div class="page-actions"><?php if($selected):?><a class="btn btn-soft" href="<?= url('guru/reports.php?student_id='.urlencode($studentId).'&type=munaqosyah') ?>"><?= svg_icon('printer',16) ?> Preview / Cetak Rapor Resmi</a><?php endif;?></div></div>
<?php if($selected):?><section class="munaqosyah-grid" data-preview-scope><article class="card"><div class="filter-row" style="margin:0 0 18px"><div><h2 class="card-title"><?= svg_icon('award') ?> <?= $existing?'Perbarui':'Input' ?> Nilai Ujian</h2><p class="card-subtitle">Kolom huruf, angka Arab, jumlah, dan predikat dihitung otomatis.</p></div><?php if($existing):?><span class="badge badge-green">Data tersimpan</span><?php endif;?></div><form action="<?= url('api/exams/index.php') ?>" method="post" data-ajax class="form-grid" data-score-group><?= csrf_field() ?><input type="hidden" name="action" value="save_munaqosyah"><div class="field full"><label>Nama Peserta Didik</label><select class="select" name="student_id" onchange="window.location.href='<?= url('guru/munaqosyah.php?student_id=') ?>'+encodeURIComponent(this.value)"><?php foreach($students as $student):?><option value="<?= e($student['id']) ?>" <?= $student['id']===$studentId?'selected':'' ?>><?= e($student['nama_lengkap'].' · '.$student['nis'].' · Kelas '.$student['kelas']) ?></option><?php endforeach;?></select></div><div class="field"><label>Tanggal Ujian</label><input class="input" type="date" name="tanggal" value="<?= e((string)($existing['tanggal']??date('Y-m-d'))) ?>" required></div><div class="field"><label>Juz</label><input class="input" name="juz" value="<?= e((string)($payload['juz']??'30')) ?>" required></div><div class="field full"><label>Periode Rapor</label><input class="input" name="bulan_tahun" value="<?= e($period) ?>" required></div><div class="section-label full">KATEGORI NILAI</div><?php foreach(['kelancaran'=>'Kelancaran','makhraj'=>'Makhorijul Huruf','tajwid'=>'Hukum Tajwid','hafalan'=>'Sambung Ayat'] as $key=>$label):?><div class="field"><label><?= e($label) ?></label><input class="input" type="number" name="nilai_<?= e($key) ?>" min="0" max="100" step="0.01" value="<?= e((string)$scoreValues[$key]) ?>" data-score="<?= e($key) ?>" required></div><?php endforeach;?><div class="section-label full"><?= svg_icon('users',16) ?> KEPRIBADIAN</div><?php foreach(['akhlaq'=>'Akhlaq','kedisiplinan'=>'Kedisiplinan','kerapihan'=>'Kerapihan'] as $key=>$label):$chosen=(string)($personal[$key]['nilai']??'B - Baik');?><div class="field"><label><?= e($label) ?></label><select class="select" name="<?= e($key) ?>"><?php foreach(['A - Sangat Baik','B - Baik','C - Cukup','D - Perlu Bimbingan'] as $option):?><option <?= $chosen===$option?'selected':'' ?>><?= e($option) ?></option><?php endforeach;?></select></div><?php endforeach;?><div class="field full"><label>Catatan Guru</label><textarea class="textarea" name="catatan_guru" placeholder="Evaluasi dan arahan untuk siswa..."><?= e((string)($existing['catatan_guru']??'')) ?></textarea></div><div class="field full"><button class="btn btn-accent" type="submit" style="width:100%">Simpan &amp; Perbarui Rapor Otomatis</button></div></form><?php if($existing):?><form action="<?= url('api/exams/index.php') ?>" method="post" data-ajax style="margin-top:10px"><?= csrf_field() ?><input type="hidden" name="action" value="delete_munaqosyah"><input type="hidden" name="student_id" value="<?= e($studentId) ?>"><input type="hidden" name="exam_id" value="<?= e($existing['id']) ?>"><button class="btn btn-danger" type="submit" style="width:100%" data-confirm="Hapus hasil Munaqosyah siswa ini?">Hapus Hasil Munaqosyah</button></form><?php endif;?></article>
<article class="card"><p class="eyebrow">PREVIEW DATA MUNAQOSYAH</p><h2 style="font-size:21px;margin:2px 0"><?= e($selected['nama_lengkap']) ?></h2><p class="muted" style="font-size:12px">Kelas <?= e($selected['kelas']) ?> · NIS <?= e($selected['nis']) ?> · Juz <?= e((string)($payload['juz']??'30')) ?></p><div class="score-hero"><div><small>Nilai Rata-rata Otomatis</small><strong data-average><?= e(number_format($average,2,'.','')) ?></strong></div><span class="predicate-pill"><span data-predicate><?= e($predicate) ?></span> · جيد جدًا</span></div><div class="score-preview"><table class="table"><thead><tr><th>Kategori Nilai</th><th>Angka</th><th>Huruf</th><th>Angka Arab</th><th>Huruf Arab</th></tr></thead><tbody><?php foreach(['kelancaran'=>'Kelancaran','makhraj'=>'Makhorijul Huruf','tajwid'=>'Hukum Tajwid','hafalan'=>'Sambung Ayat'] as $key=>$label):?><tr><td class="name"><?= e($label) ?></td><td><strong data-score-value="<?= e($key) ?>"><?= e((string)$scoreValues[$key]) ?></strong></td><td data-score-words="<?= e($key) ?>">Delapan puluh</td><td data-score-arabic="<?= e($key) ?>">٨٠</td><td dir="rtl" data-score-arabic-words="<?= e($key) ?>">ثمانون</td></tr><?php endforeach;?><tr class="summary-row"><td class="name">Jumlah</td><td><strong data-total><?= e((string)array_sum($scoreValues)) ?></strong></td><td data-total-words>Tiga ratus dua puluh</td><td data-total-arabic>٣٢٠</td><td>-</td></tr></tbody></table></div><div class="personality-preview"><div><small>AKHLAQ</small><strong data-personality="akhlaq"><?= e((string)($personal['akhlaq']['nilai']??'B - Baik')) ?></strong><span>جيد</span></div><div><small>KEDISIPLINAN</small><strong data-personality="kedisiplinan"><?= e((string)($personal['kedisiplinan']['nilai']??'B - Baik')) ?></strong><span>جيد</span></div><div><small>KERAPIHAN</small><strong data-personality="kerapihan"><?= e((string)($personal['kerapihan']['nilai']??'B - Baik')) ?></strong><span>جيد</span></div></div><div class="alert alert-success" style="margin-top:16px">Data ini terhubung ke template rapor Munaqosyah resmi.</div></article></section>
<script>document.addEventListener('DOMContentLoaded',function(){['akhlaq','kedisiplinan','kerapihan'].forEach(function(name){var select=document.querySelector('[name="'+name+'"]'),preview=document.querySelector('[data-personality="'+name+'"]');if(select&&preview)select.addEventListener('change',function(){preview.textContent=this.value;});});});</script>
